const WCHAR *TSMemoryAribKuTen(int Ku, int Ten, int *pLength)
{
	if (pLength != nullptr)
		*pLength = 0;
	if (Ku < 1 || Ku > 94 || Ten < 1 || Ten > 94)
		return nullptr;

	const int Index = (Ku - 1) * 94 + (Ten - 1);
	if (g_Length[Index] == 0)
		return nullptr;

	if (pLength != nullptr)
		*pLength = g_Length[Index];
	return &TSMemoryAribGaijiPool[g_Offset[Index]];
}


